#include <DHT.h>

#define DHTPIN 12
#define DHTTYPE DHT11

DHT dht(DHTPIN, DHTTYPE);

// Zmienne
int liczba = 0;
int minimum, maksimum;
int jasnosc = 0;
int wilgotnosc = 0;
int temperatura = 0;

char tryb = 'L';

unsigned long czasPomiaru = 0;
unsigned long czasOdswiezania = 0;

// Przycisk
bool ostatniOdczyt = HIGH;
bool stabilnyStan = HIGH;
unsigned long czasZmiany = 0;

// Cyfry wspolna anoda
const byte cyfry[10] = {
  0b0000001,
  0b1001111,
  0b0010010,
  0b0000110,
  0b1001100,
  0b0100100,
  0b0100000,
  0b0001111,
  0b0000000,
  0b0000100
};

// -------------------------
// Wyswietlanie segmentow
// -------------------------

void Znak(int numer) {

  numer = constrain(numer, 0, 9);

  byte wzor = cyfry[numer];

  byte portD = ((wzor >> 1) & 0b00111111) << 2;
  byte portB = wzor & 1;

  PORTD = (PORTD & 0b00000011) | portD;

  if (portB)
    PORTB |= 1;
  else
    PORTB &= 0b11111110;
}

// -------------------------
// Wyswietlanie dwoch cyfr
// -------------------------

void Wyswietl() {

  // Wylaczenie obu cyfr
  digitalWrite(10, LOW);
  digitalWrite(11, LOW);

  // Dziesiatki
  Znak(liczba / 10);

  digitalWrite(10, HIGH);
  delayMicroseconds(2000);
  digitalWrite(10, LOW);

  // Jednosci
  Znak(liczba % 10);

  digitalWrite(11, HIGH);
  delayMicroseconds(2000);
  digitalWrite(11, LOW);
}

// -------------------------
// Pomiar czujnikow
// -------------------------

void Pomiar() {

  int odczyt = analogRead(A0);

  if (odczyt < minimum) minimum = odczyt;
  if (odczyt > maksimum) maksimum = odczyt;

  if (maksimum > minimum) {
    jasnosc = map(odczyt, minimum, maksimum, 0, 99);
  }

  jasnosc = constrain(jasnosc, 0, 99);

  float h = dht.readHumidity();
  float t = dht.readTemperature();

  if (!isnan(h)) {
    wilgotnosc = constrain((int)h, 0, 99);
  }

  if (!isnan(t)) {
    temperatura = constrain((int)t, 0, 99);
  }

  WybierzTryb();
}

// -------------------------
// Wybor wyswietlanej wartosci
// -------------------------

void WybierzTryb() {

  switch (tryb) {

    case 'L':
      liczba = jasnosc;
      break;

    case 'H':
      liczba = wilgotnosc;
      break;

    case 'T':
      liczba = temperatura;
      break;
  }
}

// -------------------------
// Obsluga przycisku
// -------------------------

void Przycisk() {

  bool odczyt = digitalRead(9);

  if (odczyt != ostatniOdczyt) {
    ostatniOdczyt = odczyt;
    czasZmiany = millis();
  }

  if (millis() - czasZmiany >= 40) {

    if (odczyt != stabilnyStan) {

      stabilnyStan = odczyt;

      if (stabilnyStan == LOW) {

        if (tryb == 'L')
          tryb = 'H';

        else if (tryb == 'H')
          tryb = 'T';

        else
          tryb = 'L';

        WybierzTryb();

        Serial.print("Tryb: ");
        Serial.println(tryb);
      }
    }
  }
}

// -------------------------
// Setup
// -------------------------

void setup() {

  Serial.begin(9600);

  DDRD |= 0b11111100;
  DDRB |= 0b00001101;

  pinMode(9, INPUT_PULLUP);

  dht.begin();

  digitalWrite(10, LOW);
  digitalWrite(11, LOW);

  minimum = analogRead(A0);
  maksimum = minimum;

  delay(2000);

  Pomiar();

  czasPomiaru = millis();
}

// -------------------------
// Loop
// -------------------------

void loop() {

  // Odswiezanie wyswietlacza
  if (micros() - czasOdswiezania >= 4000) {

    czasOdswiezania = micros();

    Wyswietl();
  }

  // Obsluga przycisku
  Przycisk();

  // Pomiar co 2 sekundy
  if (millis() - czasPomiaru >= 2000) {

    czasPomiaru = millis();

    Pomiar();
  }
}
